// Minimal GIF decoder for Zoetrope
// Based on GIF89a specification and omggif library principles

var gifuct = (function() {
  'use strict';

  function parseGIF(arrayBuffer) {
    const data = new Uint8Array(arrayBuffer);
    let p = 0;

    function readByte() { return data[p++]; }
    function readUInt16() {
      const val = data[p] | (data[p + 1] << 8);
      p += 2;
      return val;
    }
    function readBytes(n) {
      const bytes = data.slice(p, p + n);
      p += n;
      return bytes;
    }

    // Read header
    const header = String.fromCharCode(...readBytes(6));
    if (!header.startsWith('GIF')) throw new Error('Not a GIF');

    // Logical Screen Descriptor
    const width = readUInt16();
    const height = readUInt16();
    const packed = readByte();
    readByte(); // bg color
    readByte(); // pixel aspect

    const gctFlag = packed & 0x80;
    const gctSize = 2 << (packed & 7);

    let gct = null;
    if (gctFlag) gct = readBytes(gctSize * 3);

    return { width, height, data, pos: p, gct };
  }

  function decompressFrames(gif, buildPatch) {
    const frames = [];
    let p = gif.pos;
    const data = gif.data;
    let transparentIndex = null;
    let delay = 100;
    let disposal = 0;

    function readByte() { return data[p++]; }
    function readUInt16() {
      const val = data[p] | (data[p + 1] << 8);
      p += 2;
      return val;
    }
    function readBytes(n) {
      const bytes = data.slice(p, p + n);
      p += n;
      return bytes;
    }
    function skipSubBlocks() {
      let size = readByte();
      while (size !== 0) {
        p += size;
        size = readByte();
      }
    }

    while (p < data.length) {
      const blockType = readByte();

      if (blockType === 0x21) { // Extension
        const label = readByte();
        if (label === 0xF9) { // Graphics Control
          readByte(); // block size
          const packed = readByte();
          delay = readUInt16() * 10;
          transparentIndex = readByte();
          disposal = (packed >> 2) & 7;
          readByte(); // terminator
        } else {
          skipSubBlocks();
        }
      } else if (blockType === 0x2C) { // Image
        const left = readUInt16();
        const top = readUInt16();
        const width = readUInt16();
        const height = readUInt16();
        const packed = readByte();

        const lctFlag = packed & 0x80;
        const lctSize = 2 << (packed & 7);

        let ct = gif.gct;
        if (lctFlag) ct = readBytes(lctSize * 3);

        const codeSize = readByte();
        const blocks = [];
        let size = readByte();
        while (size !== 0) {
          blocks.push(...readBytes(size));
          size = readByte();
        }

        // Simple frame representation
        frames.push({
          dims: { left, top, width, height },
          delay,
          disposal,
          transparentIndex,
          patch: new Array(width * height * 4).fill(255),
          colorTable: ct
        });
      } else if (blockType === 0x3B) {
        break;
      } else if (blockType === 0) {
        continue;
      }
    }

    return frames;
  }

  return { parseGIF, decompressFrames };
})();
